Каркас готов, заполни четыре пропуска:

```swift
for (index, week) in weeks.enumerated() {
    var weekMinutes = 0

    for minutes in ___ {
        weekMinutes += ___

        if minutes >= dailyGoal {
            currentStreak += 1
            if currentStreak > bestStreak {
